style.css:
@-moz-document domain("instagram.com") {
/* Background tổng thể */
    body, html {
        background: #ffeef5 !important; /* hồng phấn nhạt */
    }

    /* Header */
    header, nav, div[role="navigation"] {
        background: #ffd9e8 !important;
        backdrop-filter: blur(8px);
    }

    /* Sidebar + khung story */
    aside, section {
        background: #ffe6f1 !important;
    }

    /* Khung bài viết */
    article {
        background: #fff5fa !important;
        border-radius: 14px !important;
        border: 1px solid #ffd2e3 !important;
        padding: 4px !important;
    }

    /* Tên user + text */
    span, a, div {
        color: #c44579 !important; /* hồng đậm hơn cho rõ chữ */
    }

    /* Nút bấm */
    button {
        background: #ffc6dc !important;
        color: #7a1f47 !important;
        border-radius: 10px !important;
        border: 1px solid #ffb0d0 !important;
    }
    button:hover {
        background: #ffb3d3 !important;
    }

    /* Thanh search */
    input[type="text"], input[type="search"] {
        background: #ffeaf3 !important;
        border: 1px solid #ffc8dd !important;
        color: #c44579 !important;
    }

    /* Scrollbar cute luôn */
    ::-webkit-scrollbar {
        width: 10px;
    }
    ::-webkit-scrollbar-thumb {
        background: #ffb3d9;
        border-radius: 10px;
    }
    ::-webkit-scrollbar-track {
        background: #ffeef5;
    }
}
